function posSession(empty=false){if(!window.POS_SESSION){window.POS_ITEMS=JSON.parse(JSON.stringify(posLines(empty)));window.POS_SESSION=true;}}
function previewLine(item){window.POS_PREVIEW={lineId:item.id,group:item.group,product:item.name,price:posMoney(item.cents),qty:item.qty,editing:true,hasAddons:item.hasAddons,salt:item.addons.find(x=>x[0]==='Salt')?.[1]||'No salt',vinegar:item.addons.find(x=>x[0]==='Vinegar')?.[1]||'No vinegar'};}
function cartItems(){return `<div class="cart-lines">${posLines().map(x=>`<article class="cart-line" data-line-id="${x.id}"><button class="cart-item-open" data-pos-edit="${x.id}" aria-label="Customise ${esc(x.name)}"><span class="row"><strong class="cart-product">${esc(x.name)}</strong><strong class="price">$${posMoney(x.cents*x.qty)}</strong></span><span class="cart-group">${esc(groupLabel(x.group))}</span><span class="cart-summary">${x.addons.length?x.addons.map(([g,v])=>esc(g)+': '+esc(v)).join(' · '):'No add-ons'}</span>${x.note?`<span class="cart-note">Note: ${esc(x.note)}</span>`:''}</button><div class="cart-line-actions"><div class="quantity" aria-label="Quantity for ${esc(x.name)}"><button data-pos-qty="minus" data-line="${x.id}" aria-label="Decrease ${esc(x.name)}">−</button><strong>${x.qty}</strong><button data-pos-qty="plus" data-line="${x.id}" aria-label="Increase ${esc(x.name)}">+</button></div><span class="unit-price">$${posMoney(x.cents)} each</span><button data-go="19" aria-label="Note for ${esc(x.name)}">${ico('edit')}</button><button class="danger" data-pos-remove="${x.id}" aria-label="Remove ${esc(x.name)}">${ico('trash')}</button></div></article>`).join('')}</div>`;}
function cart(empty=false){const t=posTotals(empty);return `<aside class="cart hierarchy-cart"><div class="cart-head"><div class="row"><h3 style="margin:0">Current order</h3>${badge(t.lines?`${t.lines} lines · ${t.qty} qty`:'0 lines','teal')}</div><div class="row cart-meta"><span>In-store · Draft</span>${btn('Clear','danger','go30')}</div><div class="row cart-salt"><span>Order salt: <strong>Chicken salt</strong></span>${btn('Change','','go12')}</div></div><div class="cart-body">${!t.lines?'<div class="cart-empty">'+ico('bag')+'<strong>Your order starts here</strong><span>Tap a product to add it immediately.</span></div>':cartItems()}</div><div class="cart-foot"><div class="row muted"><span>Subtotal</span><span>$${t.amount}</span></div><div class="row total"><strong>Total</strong><strong>$${t.amount}</strong></div><button class="primary" ${!t.lines?'disabled':''} data-go="20">Checkout ${ico('arrow')}</button><div class="row cart-shortcuts">${!t.lines?'<button disabled>Complete</button><button disabled>Smartpay</button>':btn('Complete','','demo')+btn('Smartpay','','demo')}</div></div></aside>`;}
function orderBar(empty=false){const t=posTotals(empty);return `<button class="cartbar" ${!t.lines?'disabled':''} data-go="122"><strong>${t.lines?`View order · ${t.qty} qty`:'Order is empty'}</strong><strong>$${t.amount}${t.lines?' →':''}</strong></button>`;}
function groupGrid(){const c=layoutConfig();const groups=[...menuGroups].filter(([key])=>c.groups[key]?.visible!==false||window.POS_LAYOUT_EDITING_PREVIEW&&window.POS_LAYOUT_SHOW_HIDDEN).sort((a,b)=>{const ia=c.groupOrder.indexOf(a[0]),ib=c.groupOrder.indexOf(b[0]);return (ia<0?1000:ia)-(ib<0?1000:ib)});return `<div class="group-grid" style="${layoutGridStyle()}">${groups.map(([name,count])=>`<button class="group-card" ${window.POS_LAYOUT_EDITING_PREVIEW?`data-layout-select="group" data-layout-key="${esc(name)}" data-layout-selected="${window.POS_LAYOUT_TARGET.type==='group'&&window.POS_LAYOUT_TARGET.key===name}" data-layout-hidden="${c.groups[name]?.visible===false}"`:`data-group="${esc(name)}" data-go="118"`} style="${layoutTileStyle('group',name)}"><strong>${esc(groupLabel(name))}</strong><span class="row"><small>${count} products</small><span>→</span></span></button>`).join('')}</div>`;}
function pos(s){let group=s.id===10,quick=s.id===119,find=s.id===11;return `<div class="pos-shell"><section class="menu-pane">${group?'':`<div class="compact-context"><button class="pos-back" data-pos-back aria-label="Back to groups">${ico('back')}</button><strong>${quick?'Quick list':esc(groupLabel(window.POS_PREVIEW.group))}</strong><span class="hint">${quick?'Favourites':'Products'}</span></div>`}${group?groupGrid():productTiles(find?118:s.id)}</section>${cart(group)}</div>${orderBar(group)}`;}
function customise(s){const p=window.POS_PREVIEW;return `<div class="pos-shell"><section class="menu-pane"><div class="card addon-product"><div class="row"><button class="pos-back" data-pos-back aria-label="Back to products">${ico('back')}</button><div class="grow"><div class="addon-group-path">${esc(groupLabel(p.group))}</div><h3>${esc(p.product)}</h3><span class="muted">$${esc(p.price)} each · Quantity ${p.qty}</span></div>${badge('Already in order','green')}</div></div>${p.hasAddons===false?'<div class="card"><p class="muted">No add-ons available for this product.</p></div>':`<div class="card addon-group" data-addon-group="Salt">${section('Salt preference',badge('Required · Choose 1','amber'))}<div class="addon-choices">${['No salt','Salt','Chicken salt','Both salts','A bit salt','A bit chicken salt','A bit both salts','Extra salt','Extra chicken salt','Extra both salts'].map(x=>`<button class="addon-choice ${x===p.salt?'selected':''}" data-addon-choice aria-pressed="${x===p.salt}"><span>${x}</span><small>Included</small></button>`).join('')}</div></div><div class="card addon-group" data-addon-group="Vinegar">${section('Vinegar',badge('Optional · Choose 1'))}<div class="addon-choices">${['No vinegar','Add vinegar'].map(x=>`<button class="addon-choice ${x===p.vinegar?'selected':''}" data-addon-choice aria-pressed="${x===p.vinegar}"><span>${x}</span><small>Included</small></button>`).join('')}</div></div><div class="selection-summary"><strong>Current item</strong><span>Salt: ${esc(p.salt)} · Vinegar: ${esc(p.vinegar)}</span></div>`}<div class="addon-footer"><div class="quantity"><button data-pos-qty="minus" data-line="${p.lineId}" aria-label="Decrease quantity">−</button><strong>${p.qty}</strong><button data-pos-qty="plus" data-line="${p.lineId}" aria-label="Increase quantity">+</button></div>${btn('Item note','','go19')}<strong class="item-running-total">$${(Number(p.price)*p.qty).toFixed(2)}</strong><button class="primary" data-pos-done>Continue</button></div></section>${cart(false)}</div>${orderBar(false)}`;}
function cartReview(){const t=posTotals();return `<div class="cart-review"><div class="toolbar">${btn('‹ Continue ordering','','go10')}${btn('Clear draft','danger','go30')}</div><div class="card"><div class="row"><div><h2>Current order</h2><span class="muted">In-store · ${t.lines} lines · ${t.qty} total quantity</span></div>${badge('Draft','teal')}</div><div class="row cart-salt"><span>Order salt: <strong>Chicken salt</strong></span>${btn('Change','','go12')}</div></div><div class="cart-review-items">${cartItems()}</div><div class="review-total"><div class="row"><span>Subtotal</span><strong>$${t.amount}</strong></div><div class="row" style="margin-top:14px"><strong>Total</strong><strong style="font-size:28px">$${t.amount}</strong></div><div class="review-primary">${btn('Checkout','primary','go20')}${btn('Complete','','go120')}${btn('Smartpay','','demo')}</div></div></div>`;}
function posSearch(s){if(!(window.POS_SEARCH_OPEN??s.id===11))return '';return `<div class="overlay pos-search"><section class="dialog wide" role="dialog" aria-modal="true" aria-label="Search menu"><header class="dialog-head"><div><h2>Search menu</h2><span class="hint">Products across all groups</span></div><button class="close" data-pos-search-close aria-label="Close search">×</button></header><div class="dialog-body"><div class="search">${ico('search')}<input autofocus aria-label="Search menu products" placeholder="Product name or group…" data-pos-search-input><button class="search-clear" data-pos-search-clear aria-label="Clear search">×</button></div><p class="hint">Tap a result to add it to the current order.</p>${section('Products')}${productTiles(11)}${section('Groups')}${groupGrid()}<div class="search-no-results hint" hidden>No matching products or groups. Try another name.</div></div></section></div>`;}
function handlePOSMessage(data){if(!data.pos)return false;if(data.scroll)window.POS_VIEW_SCROLLS[current]=data.scroll;
if(data.pos==='search'){window.POS_SEARCH_ORIGIN_SCROLL=data.scroll;window.POS_SEARCH_OPEN=true;render();return true;}
if(data.pos==='close-search'){window.POS_RETURN_SCROLL=window.POS_SEARCH_ORIGIN_SCROLL;window.POS_SEARCH_OPEN=false;render();return true;}
if(data.pos==='done'||data.pos==='back'){current=data.pos==='back'&&current!==18?10:118;window.POS_RETURN_SCROLL=window.POS_VIEW_SCROLLS[current];render();return true;}
if(data.pos==='product'){window.POS_RETURN_VIEW=current===11?118:current;posSession(current===10);const item={id:'line-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),group:data.group,name:data.name,qty:1,cents:Math.round(Number(data.price)*100),hasAddons:data.hasAddons,addons:data.hasAddons?[['Salt','Chicken salt'],['Vinegar','No vinegar']]:[],note:''};window.POS_ITEMS.push(item);previewLine(item);window.POS_SEARCH_OPEN=false;if(data.hasAddons)current=18;render();return true;}
posSession(current===10);const item=window.POS_ITEMS.find(x=>x.id===(data.line||window.POS_PREVIEW.lineId));if(!item)return true;
if(data.pos==='edit'){window.POS_RETURN_VIEW=current;previewLine(item);current=18;render();return true;}
if(data.pos==='modifier'){const found=item.addons.find(x=>x[0]===data.group);if(found)found[1]=data.value;else item.addons.push([data.group,data.value]);previewLine(item);}
if(data.pos==='qty'){item.qty=Math.max(1,item.qty+(data.direction==='plus'?1:-1));if(item.id===window.POS_PREVIEW.lineId)previewLine(item);}
if(data.pos==='remove'){window.POS_ITEMS=window.POS_ITEMS.filter(x=>x.id!==item.id);}
window.POS_RETURN_SCROLL=data.scroll||null;render();return true;}
function orderCard(n=0){return `<article class="card order-card"><div class="order-head"><div class="row"><span class="order-id">#P0${19+n}</span>${badge(n===1?'08:24':'12:48','amber')}</div><p style="margin:10px 0 0;font-weight:650">${mockNames[n]}</p><p class="muted" style="margin:6px 0 0">${n===1?'Uber Eats · Delivery':'Phone pickup · Pay at counter'}</p></div><div class="order-body"><div class="row" style="margin-bottom:18px">${badge(n===1?'Paid':'Unpaid',n===1?'green':'red')}<strong class="price">${n===1?'$27.20':'$13.80'}</strong></div><div class="order-lines">3 × Potato cake<br>1 × Dim sim · fried<br>1 × $6 chips</div></div><div class="order-footer"><div class="row">${badge('Preparing','amber')}<span class="muted">Pickup 6:45 pm</span></div>${btn('Mark ready','primary','demo')}<div class="row">${btn('View order','','go3')}${btn(ico('print'),'','go4')}</div></div></article>`}
function orders(s){let cards=window.ORDER_FILTER_VALUE==='Unpaid'?orderCard(0):window.ORDER_FILTER_VALUE==='Ready'?'':orderCard(0)+orderCard(1);return cards?`<div class="three">${cards}</div>`:`<div class="empty"><h2>No ready orders</h2><p>Change or clear the active filter.</p></div>`;}
function detail(s){return `<div class="toolbar">${badge(s.id===115?'Completed':'Preparing',s.id===115?'green':'amber')}${badge(s.id===115?'Paid':'Unpaid',s.id===115?'green':'red')}<span class="muted">Order #${s.id===115?'P058':'P019'} · 17 Oct, 6:31 pm</span></div><div class="split"><div class="stack"><div class="card"><h3>Items · 3</h3>${line('3 × Potato cake','<span class="price">$6.00</span>','Chicken salt')}${line('1 × Dim sim · fried','<span class="price">$1.80</span>')}${line('1 × $6 chips','<span class="price">$6.00</span>','Chicken salt · Pack separately')}</div><div class="card"><h3>Order notes</h3><p class="muted">Pack separately. Customer will collect at the counter.</p></div></div><div class="stack"><div class="card"><h3>Customer</h3><strong>Alex Taylor</strong><p class="muted">04xx xxx 120</p>${btn('View customer','','go35')}</div><div class="card"><h3>Order total</h3><div class="row muted"><span>Payment method</span><span>${s.id===115?'DoorDash':'Pay at counter'}</span></div><div class="rule"></div><div class="row"><strong>Grand total</strong><strong style="font-size:28px">$13.80</strong></div></div></div></div><div class="page-actions">${btn('Print order','','go4')}${s.id===115?btn('View marketplace order','','demo'):btn('Cancel order','danger','demo')+btn('Mark ready','primary','demo')}</div>`}
function metrics(){return `<div class="metrics">${[['Orders','19'],['Gross sales','$602.60'],['Card','$401.90'],['Cash','$21.40']].map(x=>`<div class="metric"><div class="muted">${x[0]}</div><strong>${x[1]}</strong></div>`).join('')}</div>`}
function renderHistory(){return `<div class="toolbar">${btn('‹ Previous','','demo')}${btn('17 Oct 2026','','go7')}${btn('Next ›','','demo')}<div class="spacer"></div></div>${metrics()}${search('Search order or customer')}<div style="height:18px"></div><div class="list">${Array.from({length:9},(_,i)=>line(`#P0${19-i} · ${mockNames[i%6]}`,`<div class="row-actions">${badge('Completed')}${badge('Paid','green')}<strong>$${[13.80,66,5.80,79.70][i%4].toFixed(2)}</strong>${btn('View','','go115')}</div>`,`${6-i%4}:35 pm · ${i%3===0?'Uber Eats':'In-store'} · ${i+1} items`)).join('')}</div>`}
function empty(s){let label=s.id===5?'No deliveries on the way':s.id===32?'No upcoming orders':s.id===108?'You’re all caught up':s.id===112?'No orders for this date':s.id===114?'No linked customer':'Nothing to resolve';return `<div class="toolbar">${s.id===112?btn('17 Oct 2026','','go7'):''}<div class="spacer"></div>${s.area==='orders'?'':btn('Refresh','','demo')}</div><div class="empty"><div class="empty-icon">${ico(s.id===114?'people':'check')}</div><h2>${label}</h2><p>${esc(s.note)}</p>${btn(s.id===112?'Change date':s.id===114?'Back to order':s.id===117?'Back to Marketplace':'Refresh',s.id===112?'primary':'',s.id===112?'go7':s.id===114?'go3':s.id===117?'go46':'demo')}</div>`}
function people(s){return `<div class="toolbar">${search('Search customers by name, phone or email')}${btn(s.id===33?'New customer':'Recent calls',s.id===33?'primary':'',s.id===33?'go34':'go29')}</div><div class="list">${mockNames.map((n,i)=>`<div class="list-row"><span class="initial">${n.split(' ').map(x=>x[0]).join('')}</span><div class="grow"><strong>${n}</strong><small>04xx xxx ${120+i} · ${i+2} orders · Last visit 17 Oct</small></div>${badge(`${[120,85,64,42,25,10][i]} pts`,'teal')}${btn(s.id===28?'Select':'View',s.id===28?'primary':'','go35')}</div>`).join('')}</div>`}
function profile(s){return `<div class="profile-head"><span class="initial">AT</span><div><h2>Alex Taylor</h2><span class="muted">Customer since September 2026</span></div></div><div class="metrics">${[['Orders','12'],['Total spend','$385.40'],['Reward points','120'],['Last order','17 Oct']].map(x=>`<div class="metric"><span class="muted">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="two"><div class="stack"><div class="card"><h3>Contact details</h3><p>04xx xxx 120</p><p class="muted">alex@example.invalid</p>${btn('Edit name','','go36')}</div><div class="card"><h3>Recent orders</h3>${line('#P019',btn('View order','','go3'),'17 Oct · Preparing · $13.80')}${line('#P058',btn('View order','','go115'),'12 Oct · Completed · $13.80')}</div></div><div class="stack"><div class="card"><h3>${s.id===37?'Adjust points':'Rewards'}</h3>${s.id===37?fields(s.fields)+`<div class="banner">Current 120 pts → New balance shown after entry</div>`+btn('Save points','primary','demo'):line('Earned from order #P019',badge('+14 pts','green'),'17 Oct 2026')+btn('Adjust points','','go37')}</div><div class="card"><h3>Coupons & offers</h3>${line('WELCOME10',badge('Active','green'),'10% off · Ends 31 Oct')}${btn('Marketing email','','go39')}</div></div></div>`}
function checkout(s){let selected=({20:1,22:1,25:2,26:3,27:0})[s.id]||0;let body=`<div class="checkout-summary card"><div class="row"><strong>Current order · 3 items</strong><strong>$11.80</strong></div><p class="muted">2 × Potato cake · Dim sim · Small chips</p>${btn('Review / edit items','','go122')}</div>${tabs(['In-store','Pickup','Delivery','Third-party'],selected)}<div class="card"><h3>Customer ${selected===0?'<span class="muted">· optional</span>':''}</h3><div class="form-grid">${field('Phone','04')}${field('Customer name')}</div><div class="row-actions">${btn('Find customer','','go28')}${btn('Recent calls','','go29')}</div></div>`;if(s.id===25)body+=section('Delivery details')+`<div class="card">${fields(['Delivery address','Delivery instructions'])}${btn('Get delivery quote','','demo')}</div>`;if(s.id===26)body+=section('External order')+`<div class="card">${chips(['Uber Eats','DoorDash'])}${fields(['Customer name','External order ID'])}<p class="hint">Payment is handled by the selected marketplace.</p></div>`;body+=section('Discount',btn('Add discount','','go21'));if(s.id===22||s.id===20)body+=`<div class="card"><h3>Pickup time</h3>${chips(['ASAP','Pre-order'],s.id===22?1:0)}${s.id===22?`<div class="form-grid" style="margin-top:16px">${field('Pickup date','18 Oct 2026')}${field('Pickup time','6:45 pm')}</div>`:''}</div>`;if(s.id===27)body+=`<div class="card">${section('Payment')}${chips(['Card','Cash','Unpaid'])}<p class="hint">Choose a method when completing this order.</p></div>`;body+=`<div style="margin-top:20px">${field('Order note')}</div><div class="page-actions">${btn('Back to order','','go118')}${btn(s.id===27?'Complete order':s.id===25?'Review delivery':'Create pickup order','primary',s.id===27?'go120':'demo')}</div>`;return `<div class="pos-shell"><section class="menu-pane">${body}</section>${cart(false)}</div>`}
function marketing(s){let step=s.id===39?0:s.id===40?1:2;return `<div class="steps">${['Campaign','Recipients','Review & send'].map((x,i)=>`<span class="step ${step===i?'current':''}"><b>${i+1}</b>${x}</span>`).join('<span style="color:#a8bbbf">—</span>')}</div>${step===0?`<div class="split"><div class="card">${fields(s.fields)}<div class="row-actions">${btn('Generate copy','','demo')}${btn('Generate image','','demo')}</div></div><div class="card"><h3>A reason to come back</h3><p class="muted">Build a short offer for your regular customers. You’ll choose who receives it next.</p><div class="tv-art"><strong>Pappa’s Ocean Catch</strong><span>YOUR NEXT FAVOURITE MEAL</span><em>10% off</em></div><p class="hint">Illustrative local preview · Nothing sent</p></div></div>`:step===1?`<div class="toolbar">${search('Search recipients')}${btn('Filter & sort','','go41')}</div><div class="banner">1 recipient selected · <strong>Select all visible</strong> · Clear selection</div><div class="list">${mockNames.map((n,i)=>line(n,btn(i===0?'Selected':'Select',i===0?'primary':'','demo'),`Email available · ${i+2} orders · Last contacted ${i+1} months ago`)).join('')}</div>`:`<div class="banner amber">${ico('warning')}<span><strong>Review before sending</strong><br>1 email recipient selected. Sending contacts customers and cannot be undone.</span></div><div class="two"><div class="card"><h3>Email preview</h3><p class="muted">Subject: Your next meal at Pappa’s</p><div class="rule"></div><h2>Fancy fish & chips tonight?</h2><p style="line-height:1.7">Enjoy 10% off your next order. We’d love to see you again at Pappa’s Ocean Catch.</p>${badge('Local draft · Unsent','amber')}</div><div class="card"><h3>Recipients · 1</h3>${line('Alex Taylor','', 'alex@example.invalid')}${btn('Edit recipients','','go40')}<div class="rule"></div><h3>SMS preview</h3><p class="muted">No SMS recipients selected.</p>${btn('Send SMS · 0 recipients','','demo')}</div></div>`}<div class="page-actions">${btn('Back','','demo')}${btn(s.primary,'primary',step===0?'go40':step===1?'go42':'demo')}</div>`}
function coupons(s){return `<div class="toolbar">${search('Search code or offer')}${btn('Refresh','','demo')}</div>${chips(['All','Active','Inactive','Expired'],s.id===45?1:0)}<div class="three" style="margin-top:18px">${Array.from({length:6},(_,i)=>`<div class="card coupon"><div class="row"><span class="coupon-code">WELCOME${10+i}</span>${badge(i%3===0&&s.id!==45?'Expired':'Active',i%3===0&&s.id!==45?'':'green')}</div><div class="offer">10% off</div><p class="muted">Your next Pappa’s order · Min. $20</p><p class="hint">0 / 1 uses · Ends 31 Oct 2026</p><div class="rule"></div><div class="row">${btn('Copy code','','demo')}${btn('Details','','go44')}</div></div>`).join('')}</div><div class="toolbar" style="margin-top:20px"><span class="muted">Showing 1–6 of 24</span><div class="spacer"></div>${btn('Previous','','demo')}${btn('Next','','demo')}</div>`}
function marketplace(s){return `<div class="two"><div class="card"><div class="row"><h3>Uber Eats</h3>${badge('Not configured','amber')}</div><p class="muted">Connect your store to load marketplace orders.</p>${btn('Configure connection','','go47')}</div><div class="card"><div class="row"><h3>DoorDash</h3>${badge('Not configured','amber')}</div><p class="muted">Manage connection and synchronisation.</p>${btn('Configure connection','','go48')}</div></div>${section('Menu name mapping',btn('Resolve names','','go49'))}<div class="banner">Match external menu names to internal POS products and add-ons.</div>${tabs(['Uber Eats','DoorDash'],s.id===50?1:0)}${tabs(['Active','Scheduled','History'],s.id===53?1:s.id===50?2:0)}${s.id===50?`<div class="toolbar">${btn('Today','','go52')}${btn('All statuses','','go51')}${btn('Refresh','','demo')}</div>`:''}<div class="card"><div class="empty" style="min-height:220px"><div class="empty-icon">${ico('bag')}</div><h2 style="font-size:21px">Connect to view ${s.id===53?'scheduled ':s.id===50?'past ':''}orders</h2><p>Configure the selected marketplace to retrieve orders.</p></div></div>`}
function mapping(){return `${search('Search unresolved names')}<div class="banner amber" style="margin-top:20px">3 sample names need a match. Suggestions are not saved automatically.</div><div class="stack">${['Mix souvlaki with the lot','Both plain and chicken salt','Coke Zero Sugar 1.25 L'].map((x,i)=>`<div class="card"><div class="row"><h3>${x}</h3>${badge(i===0?'Product':i===1?'Add-on':'Product')}</div><p class="hint">External marketplace name → Internal POS match</p>${search('Find internal item')}${chips(i===0?['Mix souvlaki','Mix souvlaki with the lot']:i===1?['Chicken salt','Both salts']:['Coke Zero 1.25 L'])}<div class="page-actions" style="position:static;background:none">${btn('Save mapping','primary','demo')}</div></div>`).join('')}</div>`}
function chart(){return `<svg class="chart" viewBox="0 0 900 210" preserveAspectRatio="none" role="img" aria-label="Illustrative sales trend, not actual business data"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#85bfb5" stop-opacity=".4"/><stop offset="100%" stop-color="#85bfb5" stop-opacity="0"/></linearGradient></defs>${[30,80,130,180].map(y=>`<path d="M0 ${y}H900" stroke="#e1e8e8"/>`).join('')}<path d="M0 150 80 160 160 120 240 140 320 75 400 110 480 55 560 85 640 25 720 70 800 85 900 120" fill="none" stroke="#a9b9bd" stroke-width="2" stroke-dasharray="5 5"/><path d="M0 170 80 155 160 160 240 110 320 130 400 70 480 105 560 35 640 80 720 55 800 125 900 140V210H0z" fill="url(#fade)"/><path d="M0 170 80 155 160 160 240 110 320 130 400 70 480 105 560 35 640 80 720 55 800 125 900 140" fill="none" stroke="#087f82" stroke-width="3"/></svg>`}
function reports(s){let i=({57:0,59:1,60:2,61:3})[s.id]||0;return `${tabs(['Daily','Weekly','Monthly','Last X days'],i)}<div class="toolbar">${btn('‹ Previous','','demo')}${btn(i===0?'17 Oct 2026':i===1?'12–18 Oct 2026':i===2?'October 2026':'Last 15 complete days','','go58')}${btn('Next ›','','demo')}<div class="spacer"></div>${btn('Print report','','go62')}${i===3?btn('About this period','','go64'):''}</div>${i===3?chips(['7 days','15 days','30 days','60 days','Custom'],1):''}<div class="metrics six">${[['Gross sales',i===0?'$603':'$9,709'],['Net sales',i===0?'$510':'$8,303'],['Paid orders',i===0?'19':'302'],['Average order','$32'],['Discounts',i===0?'$5':'$117'],['Vs. prior period',i===0?'−$1,935':'−$4,109']].map(x=>`<div class="metric"><span class="muted">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="card"><div class="row"><h3>Gross sales ${i===0?'by 30 minutes':'by date'}</h3><span class="hint">● Current　┄ Prior period</span></div>${chart()}<div class="row hint"><span>${i===0?'11 am':'Start of period'}</span><span>${i===0?'3 pm':'Midpoint'}</span><span>${i===0?'8 pm':'End of period'}</span></div></div>${section('Breakdown')}<div class="two"><div class="card"><h3>Payment methods</h3>${line('Card','$402')}${line('Marketplace','$179')}${line('Cash','$21')}</div><div class="card"><h3>${i===0?'Sales by channel':'Sales by date'}</h3>${line(i===0?'At counter':'Mon, 12 Oct','$241')}${line(i===0?'Phone pickup':'Tue, 13 Oct','$182')}${line(i===0?'Online':'Wed, 14 Oct','$179')}</div></div>`}
const settingGroups=[['Catalogue',[['Store information',67,'Business name, address and opening hours'],['Menu products & categories',77,'Manage menu and pricing'],['Add-on groups',86,'Choices and modifiers'],['POS layout',13,'Arrange groups and shortcuts']]],['Register',[['Refresh interval',68,'Every 30 seconds'],['Order sound',69,'Notifications and preview'],['Live order cards',70,'Density and orientation'],['Marketplace auto-sync',71,'Intervals and operating hours'],['Caller ID',72,'Listener and diagnostics']]],['Printing',[['Kitchen printers',74,'Connections and saved printers'],['Section routing',104,'Fried, grilled and till'],['Receipt options',106,'Automatic printing and receipts'],['Print diagnostics',73,'Diagnostic footer and register name'],['Print journal',107,'Recent print events']]],['Storage & integrations',[['Refresh POS catalogue',102,'Reload menu data on this device'],['Export POS settings',102,'Download a configuration backup'],['Import POS settings',102,'Restore an existing backup'],['Smartpay pairing',76,'Connect payment terminal']]]];
function settings(){return `<div class="setting-grid">${settingGroups.map(([t,r])=>`<div class="card"><h3>${t}</h3>${r.map(([n,id,h])=>`<div class="setting-row"><div><strong>${n}</strong><small>${h}</small></div>${btn(ico('arrow'),'','go'+id)}</div>`).join('')}</div>`).join('')}</div><div class="page-actions">${btn('Save settings','primary','demo')}</div>`}
function form(s){let vals=s.id===67?{'Shop name':"Pappa’s Ocean Catch",'Legal company name':'Example business Pty Ltd','Opening hours':'Mon–Thu 11:00–20:30\nFri 11:00–21:00\nSat–Sun 11:00–20:30'}:s.id===68?{'Refresh interval (seconds)':'30'}:s.id===72?{'SIP UDP port':'5060','Inactivity timeout (seconds)':'60'}:s.id===73?{'Register name':'Counter iPad'}:{};return `<div class="card" style="max-width:940px">${s.id===76?`<div class="banner amber">Terminal not paired · Enter the code from your payment terminal.</div>`:''}${s.id===56?`<div class="banner">Get a quote before requesting a courier.</div>`:''}<div class="${s.fields.length>5?'form-grid':''}">${fields(s.fields,vals)}</div>${s.id===69?btn('Preview sound','','go101'):''}${s.id===72?`<details><summary>Diagnostics</summary>${chips(['None','Trying','Ringing','Trying + Ringing','OK','Trying + OK','Busy (486)','Unavailable (480)'])}</details>`:''}${s.id===76?btn('Save configuration','','demo'):''}</div><div class="page-actions">${btn('Cancel','','demo')}${btn(s.primary,'primary','demo')}</div>`}
function catalogue(s){return `${tabs(['Products','Categories','Add-on groups'],s.id===84?1:0)}<div class="toolbar">${search(s.id===84?'Search categories':'Search products')}${btn(s.primary,'primary',s.id===84?'go85':'go78')}</div>${s.id===77?chips(['All','Packs','Fish','Chips','Sides','Burgers']):''}<div class="list" style="margin-top:18px">${(s.id===84?['Packs','Salad','Fish','Chips','Sides','Beef burgers','Chicken burgers']:productData.map(x=>x[0])).map((x,i)=>line(esc(x),`<div class="row-actions">${badge(s.id===84?`${8+i} items`:'Active','green')}${btn('Edit','','go'+(s.id===84?'85':'78'))}${btn('Delete','danger','demo')}</div>`,s.id===84?'Kitchen: Fried · Sort '+i:`${productData[i][2]} · $${productData[i][1]}`)).join('')}</div>`}
function product(s){let index=({78:0,79:1,80:2,81:2,82:4,83:3})[s.id];let body='';if(index===0)body=`<div class="form-grid">${fields(['Name','Price','Description','Kitchen section: Fried, Grilled, Till','Search terms','Image URL','Sort order','Preparation time (minutes)'])}</div>`;if(index===1)body=fields(['Slug','SEO title','SEO description']);if(index===2)body=`<div class="form-grid">${fields(['Warning threshold units','Alert threshold units'])}</div>${section('Inventory ingredients',btn('Link inventory product','','go81'))}<div class="card"><p class="muted">No inventory products linked yet.</p></div>`;if(index===3)body=`<p class="muted">Choose modifier groups available for this product.</p>${['Can option','Second can option','1.25 L drink option','Sour option','Sugar option','Salt option','Sauce option','Fish replacement'].map((x,i)=>`<div class="switch-row"><span>${x}</span><button role="switch" aria-checked="${i===5}" data-toggle style="border:0;background:none"><span class="toggle ${i===5?'':'off'}"></span></button></div>`).join('')}`;if(index===4)body=`<div class="empty" style="height:250px;min-height:220px"><div class="empty-icon">${ico('bag')}</div><h2 style="font-size:22px">Build a bundle</h2><p>Add included products and quantities.</p>${btn('Add included item','','demo')}</div>`;return `${tabs(s.tabs,index)}${body}`}
function addons(s){return `<div class="toolbar">${search('Search groups or items')}${btn('Add group','primary','go87')}</div><div class="stack">${['Can option','Salt option','Sauce option','Fish replacement'].map((x,i)=>`<div class="card"><div class="row"><div><h3>${x}</h3><span class="hint">${i===0?8:5} items · Active · ${i===1?'Required':'Optional'}</span></div><div class="row-actions">${btn(s.id===88&&i===0?'⌃':'⌄','','go88')}${btn('Add item','','demo')}${btn('Edit','','go87')}${btn('Delete','danger','demo')}</div></div>${s.id===88&&i===0?['Coke can','Coke Zero Sugar can','Coke Vanilla can','Fanta can'].map(x=>line(x,`<div class="row-actions"><span>$0.00</span>${btn('Edit','','demo')}${btn('Delete','danger','demo')}</div>`,'Default price · Active')).join(''):''}</div>`).join('')}</div>`}
function printers(s){return `${tabs(['Connections','Saved printers','Section routing','Receipt options','Journal'],s.id===103?1:0)}<div class="two"><div class="card"><h3>${s.id===75?'Edit saved printer':'Printer connection'}</h3>${fields(s.fields,{'Printer IP address':'192.168.x.x','Port':'9100','Printer name (optional)':'Till'})}<div class="row-actions">${btn('Discover printers','','demo')}${btn(s.id===75?'Update printer':'Add printer','primary','demo')}</div></div><div class="card"><h3>Saved printers</h3>${['Till','Simulator','TM-m30II','Shop printer'].map((x,i)=>`<div class="setting-row"><div><strong>${x}</strong><small>${i===1?'Preview only':'TCP / IP · Port 9100'}</small></div>${i===0?badge('Default','teal'):btn('Set default','','demo')}</div><div class="row-actions" style="justify-content:flex-end">${btn('Edit','','go75')}${btn('Remove','danger','demo')}</div>`).join('')}</div></div>`}
function routing(s){return `${tabs(['Connections','Saved printers','Section routing','Receipt options','Journal'],2)}<div class="banner">Route each kitchen section independently. Combine groups items; Separate prints individual tickets.</div><div class="stack">${(s.id===104?['Default route','Fried']:['Grilled','Till']).map(x=>`<div class="card route-card"><div class="row"><h3>${x}</h3>${badge('Enabled','green')}</div>${field('Printer: Till, TM-m30II, Shop printer, Simulator')}${field('Print mode: Combine, Separate')}${field('Template: Kitchen, Customer copy')}<div class="form-grid">${field('Enabled from','11:00')}${field('Enabled to','20:30')}</div>${btn('Remove route','danger','demo')}</div>`).join('')}</div><div class="page-actions">${btn('Add section printer','','demo')}${btn('Done','primary','demo')}</div>`}
function calls(s){return `<div class="toolbar">${search('Search caller or phone')}${btn('Refresh','','demo')}</div>${chips(['All time','Today','Yesterday'],s.id===89?1:s.id===90?2:0)}<div class="list" style="margin-top:18px">${mockNames.map((x,i)=>`<div class="list-row"><span class="initial">${ico('phone')}</span><div class="grow"><strong>${x}</strong><small>04xx xxx ${120+i} · ${s.id===90?'Yesterday':'Today'}, ${5+i%3}:4${i} pm</small></div>${badge(i===3?'Missed':'Accepted',i===3?'red':'green')}<div class="row-actions">${btn('Customer','','go35')}${btn('Call back','','demo')}</div></div>`).join('')}</div>`}
function tv(s){return `<div class="toolbar"><p class="muted">Menu images displayed on your connected TVs.</p><div class="spacer"></div>${btn('Upload menu image','primary','go95')}</div><div class="three">${['Burgers & souvlaki','Packs & sides','Opening hours','Fish & salad','Flathead special'].map((x,i)=>`<div class="card"><div class="tv-art"><strong>Pappa’s<br>Ocean Catch</strong><span>${x.toUpperCase()}</span>${i===4?'<em>$10</em>':''}</div><div class="row" style="margin:18px 0 8px"><h3 style="margin:0">${x}</h3>${badge(i===2?'Inactive':'Active',i===2?'':'green')}</div><p class="hint">1920 × 1080 · Position ${i+1}</p><div class="row-actions">${btn('Preview','','go94')}${btn('Download','','demo')}</div><div class="row-actions" style="margin-top:10px">${btn('Move ↑','','demo')}${btn('Move ↓','','demo')}${btn('Delete','danger','demo')}</div><div class="switch-row"><span>Visible on TV</span><button role="switch" aria-checked="${i!==2}" data-toggle style="border:0;background:none"><span class="toggle ${i===2?'off':''}"></span></button></div></div>`).join('')}</div>`}
function about(){return `<div class="two"><div class="card"><h3>Installed build</h3>${line('Version','Installed version','Read from app build metadata')}${line('Build date','Installed build date')}${line('Revision','Installed revision')}<div class="row-actions" style="margin-top:20px">${btn('Check for update','primary','demo')}${btn('Restart app','','demo')}</div></div><div class="stack"><div class="card"><h3>Network</h3>${line('Local IP address','192.168.x.x')}</div><div class="card"><h3>Memory diagnostics</h3><p class="muted">Device memory, native heap and JavaScript memory appear here when available.</p>${btn('Refresh diagnostics','','demo')}</div></div></div>`}
function navigation(){return `<div class="setting-grid">${[['Service',[['Live orders',1],['Take an order',118],['Pre-orders',32],['Order history',113],['Deliveries',54]]],['Customers',[['Customers',33],['Marketing',39],['Coupons',43],['Call history',89]]],['Manage',[['Marketplace',46],['Menu catalogue',77],['Sales reports',57],['TV menus',93]]],['Register',[['Settings',66],['About',92],['Profile',96],['Sign out',97]]]].map(([t,r])=>`<div class="card"><h3>${t}</h3>${r.map(([x,id])=>`<div class="setting-row"><strong>${x}</strong>${btn(ico('arrow'),'','go'+id)}</div>`).join('')}</div>`).join('')}</div>`}
function login(s){return `<div class="login"><section class="login-art"><div class="wordmark">Pappa’s Ocean Catch</div><div><div class="eyebrow" style="color:#a4c3ca">YOUR COUNTER, CONNECTED</div><h2>A good service<br>starts here.</h2><p>Orders, customers and your kitchen. Together in one calm workspace.</p></div><div class="foot muted" style="color:#a4c3ca">Pappa’s · Fish, Chips & Burgers</div></section><section class="login-form"><div class="login-box"><div class="eyebrow">PAPPAS ORDER MANAGEMENT</div><h1>Welcome back</h1><p class="muted">Sign in to your store workspace.</p><form>${s.id===100?'<div class="banner amber" role="alert">Enter your email and password to continue.</div>':''}${field('Email')}${s.id===100?'<p class="error-text" style="color:#b53535;margin-top:-15px">Enter your email address.</p>':''}${field('Password')}${s.id===100?'<p style="color:#b53535;margin-top:-15px;font-size:14px">Enter your password.</p>':''}${btn('Sign in','primary','demo')}</form><p class="copyright">Store access · Authorised team members</p></div></section></div>`}
function bodyFor(s){switch(s.kind){case'orders':return orders(s);case'preorders':return preorders(s);case'pos':return pos(s);case'history':return renderHistory(s);case'detail':return detail(s);case'empty':return empty(s);case'people':return people(s);case'profile':return profile(s);case'checkout':return checkout(s);case'marketing':return marketing(s);case'coupons':return coupons(s);case'marketplace':return marketplace(s);case'mapping':return mapping(s);case'reports':return reports(s);case'settings':return settings(s);case'form':return form(s);case'catalogue':return catalogue(s);case'addons':return addons(s);case'printers':return printers(s);case'routing':return routing(s);case'calls':return calls(s);case'tv':return tv(s);case'about':return about(s);case'navigation':return navigation();case'layout':return layout(s);case'journal':return `<div class="toolbar">${search('Search journal')}${chips(['All','Print','Connection','Performance'])}</div><div class="list">${['Print job completed','Printer connection restored','JavaScript event loop stalled','Print job queued','Receipt template prepared'].map((x,i)=>line(x,badge(i===2?'Warning':'Info',i===2?'amber':''),`6:${40-i} pm · Counter iPad · ${i===2?'Expand to view diagnostic detail':'No customer data stored in preview'}`)).join('')}</div>`;case'error':return `<div class="toolbar">${search('Search customer or address')}${btn('New delivery','primary','go56')}</div>${chips(['Today','Last 7 days'],s.id===55?1:0)}<div class="empty"><div class="empty-icon">${ico('warning')}</div><h2>Deliveries couldn’t load</h2><p>Check your connection and try again. Your selected date range is saved.</p>${btn('Try again','primary','demo')}</div>`;default:return ''}}
function overlayBody(s){if(s.id===62)return `<p class="hint">Tap a printer to print immediately.</p><div class="printer-buttons">${s.fields.map(name=>`<button data-print-printer="${esc(name)}">${ico('print')}<span><strong>${esc(name)}</strong><small>${/simulator/i.test(name)?'Open preview':'Print now'}</small></span>${ico('arrow')}</button>`).join('')}</div>`;if(s.id===4)return `<p class="hint">Choose the copy, then tap a printer.</p><div class="printer-buttons">${s.fields.map(name=>`<button data-print-copy="${esc(name)}"><strong>${esc(name)}</strong>${ico('arrow')}</button>`).join('')}</div>`;if(s.id===81)return `${search('Search inventory products')}<div class="list" style="margin-top:16px">${['Flake · FLA-001','Flake · FLA-002','Barramundi fillet · BAR-001','Basa fillet · BAS-001','Chicken breast · CHK-001'].map(x=>line(x,btn('Select','','demo'),'Inventory product')).join('')}</div>`;if(s.kind==='product')return product(s);if(s.kind==='date')return `${chips(['Today','Yesterday','Custom'])}<div class="row" style="margin:20px 0">${btn('‹','','demo')}<strong>October 2026</strong>${btn('›','','demo')}</div><div class="calendar">${['Mo','Tu','We','Th','Fr','Sa','Su'].map(x=>`<span>${x}</span>`).join('')}${Array.from({length:35},(_,i)=>i<3||i>33?'<span></span>':btn(i-2,i===19?'primary':'','demo')).join('')}</div>`;
 if(s.kind==='cash')return `<div class="cash-summary"><span>Amount due</span><div class="cash-total">$11.80</div><div class="row"><span>Tendered</span><strong>$50.00</strong></div><div class="row" style="margin-top:10px"><span>Change</span><strong style="font-size:24px;color:#a0dfc3">$38.20</strong></div></div>${field('Amount tendered','50.00')}${chips(['Exact','$5','$10','$20','$50','$100'],4)}<div class="keypad">${['7','8','9','4','5','6','1','2','3','.','0','⌫'].map(x=>btn(x,'','demo')).join('')}</div><div style="margin-top:12px">${btn('Clear tender','','demo')}</div>`;
 if(s.kind==='keypad')return `${field('Phone number','04')}<div class="keypad">${['1','2','3','4','5','6','7','8','9','03','0','⌫'].map(x=>btn(x,'','demo')).join('')}</div><p class="hint">On a phone, use the native telephone keyboard.</p>`;
 if(s.kind==='confirm')return `<div class="empty" style="height:auto;min-height:190px"><div class="empty-icon">${ico('warning')}</div><p>${esc(s.note)}</p></div>`;
 if(s.kind==='receipt')return `<div class="receipt"><h3>PAPPA’S OCEAN CATCH</h3><p style="text-align:center">SALES REPORT<br>17 OCTOBER 2026<br>Sample layout only</p><hr>${[['Gross sales','$603.00'],['Net sales','$510.00'],['Paid orders','19'],['Average order','$32.00'],['Discounts','$5.00'],['Card','$402.00'],['Marketplace','$179.00'],['Cash','$21.00']].map(x=>`<div class="row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<hr><p style="text-align:center">SIMULATOR PREVIEW<br>No physical print requested</p></div>`;
 if(s.kind==='tvpreview')return `<div class="tv-art" style="min-height:300px"><strong>Pappa’s Ocean Catch</strong><span>FISH, CHIPS & BURGERS</span><em>Freshly made.<br>Always a favourite.</em></div><p class="hint">Menu asset preview · Use the actual uploaded image in implementation.</p>`;
 if(s.kind==='system')return `<div class="banner">${ico('image')}<span>Native system interface</span></div><h3>${s.id===95?'Choose an image from Files or Photos':'Open Pappas Order Management?'}</h3><p class="muted">${esc(s.note)}</p><div class="diagram-preview" style="margin-top:24px"><strong>${s.id===95?'Upload entry → Native file picker → Preview → Save':'Validated app link → OS prompt → Destination'}</strong><p class="hint">This panel specifies the system handoff. It does not replace the operating-system dialog.</p></div>`;
 if(s.id===81)return `${search('Search inventory products')}<div class="list" style="margin-top:16px">${['Flake · FLA-001','Flake · FLA-002','Barramundi fillet · BAR-001','Basa fillet · BAS-001','Chicken breast · CHK-001'].map((x,i)=>line(x,btn('Select','','demo'),'Inventory product · '+(i+1)+' units')).join('')}</div>`;
 let body=s.fields.map((f,i)=>{
 if(/^(Required|Allow multiple|Active|Active status)$/.test(f))return field(f);
 if(s.id===15)return i===0?field(f,'#087F82'):field(f);
 if(s.id===21)return i===0?field(f):field(f,i===1?'10':'');
 if(s.id===17)return i===0?field(f):'<h3>Include menu groups</h3>'+['Packs','Fish','Chips','Sides','Burgers','Souvlaki','Drinks'].map((x,j)=>`<label class="choice"><input type="checkbox" ${j===0?'checked':''}> ${x}</label>`).join('');
 if(f.includes(':')&&!f.includes(', ')){let [k,...v]=f.split(':');return `<div class="setting-row"><strong>${esc(k)}</strong><span>${esc(v.join(':'))}</span></div>`}
 if(f.includes(': '))return field(f);
 if(/name|header|ID|key|^Hex|^Percentage|^Fixed amount|^Coupon code|note|Brightness|^Sort order|description/i.test(f)&&![2,4,12,29,51,52,62,64,101,120].includes(s.id))return field(f);
 return `<label class="choice ${i===0?'selected':''}"><input type="radio" name="choice" ${i===0?'checked':''}>${esc(f)}</label>`;
 }).join('');if(s.id===64)body=`<p class="muted">${esc(s.fields[0])}</p>`;if(s.id===21)body=chips(['5%','10%','15%','20%','25%'],1)+body+'<div class="banner">Subtotal $11.80 − 10% ($1.18) = <strong>$10.62</strong></div>';if(s.id===15)body+='<div style="height:80px;background:#087f82;border-radius:16px"></div>';return body;}
window.ORDER_PREVIEW_UPCOMING=false;
function orderTabs(s){if(s.area!=='orders')return '';const upcoming=s.id===123||window.ORDER_PREVIEW_UPCOMING&&s.id!==32;const active=s.id===5?5:[6,7,8,115].includes(s.id)?6:s.id===123?123:[1,2,3,4,108].includes(s.id)?1:0;const entries=[['Live',1,s.id===108?0:2],['On the way',5,0],['Completed',6,19]];if(upcoming)entries.push(['Pre-orders',123,2]);return `<nav class="order-tabs" aria-label="Order status tabs" role="tablist">${entries.map(([label,id,count])=>`<button role="tab" aria-selected="${active===id}" class="order-tab ${active===id?'active':''}" data-go="${id}">${label}<span>${count}</span></button>`).join('')}</nav>`;}
function preorders(){return `<div class="toolbar"><div><h2 style="margin:0;font-size:24px">Upcoming collections</h2><p class="muted">2 scheduled orders · Sorted by collection time</p></div><div class="spacer"></div>${btn('Refresh','','demo')}</div><div class="two">${[['P021','Alex Taylor','Tomorrow · 12:30 pm','30.50','Flake pack for two'],['P022','Jordan Lee','Tomorrow · 6:00 pm','58.00','Family flake pack']].map(([ref,name,time,total,item])=>`<article class="card"><div class="row"><h3>#${ref}</h3>${badge('Pre-order','teal')}</div><div class="scheduled-time">${time}</div><strong>${name}</strong><p class="muted">Pickup · ${item}</p><div class="row"><span class="price">$${total}</span>${badge('Unpaid','red')}</div><div class="rule"></div>${btn('View order','','go3')}</article>`).join('')}</div>`;}
window.ORDER_FILTER_OPEN=null;window.ORDER_FILTER_VALUE='All orders';
function orderFilterIsOpen(s){return window.ORDER_FILTER_OPEN??s.id===2;}
function orderFilterPanel(s){if(s.area!=='orders'||!orderFilterIsOpen(s))return '';return `<section class="orders-filter-panel" id="order-filter-panel" aria-label="Order filters"><div class="filter-options">${['All orders','Needs action','Unpaid','Ready','Scheduled'].map(v=>`<button class="chip ${window.ORDER_FILTER_VALUE===v?'selected':''}" data-order-filter="${v}">${v}</button>`).join('')}</div><button class="advanced-filters" data-go="8">More filters</button></section>`;}
function headerIcon(name,label,attrs=''){return `<button class="header-icon" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${ico(name)}</button>`;}
function shell(s,body){const posBrowse=s.area==='pos'&&['pos','customise'].includes(s.kind);const isOrders=s.area==='orders';const title=posBrowse?(s.kind==='customise'?'Update item':'Take order'):isOrders&&s.kind!=='detail'?'Orders':s.area==='settings'&&s.screen==='pos-layout'?'POS layout':s.title;let active=s.area==='pos'?'pos':['customers','marketing','coupons'].includes(s.area)?'people':s.area==='reports'?'reports':isOrders?'orders':'more';let nav=[['orders','Orders',1],['pos','Take order',10],['people','Customers',33],['reports','Reports',57],['more','More',31]];let rail=nav.map(([i,t,n])=>`<div class="rail-item ${i===active?'active':''}" data-go="${n}">${ico(i)}${t}</div>`).join('');return `<div class="app"><aside class="rail"><div class="brand">p.</div>${rail}<div class="rail-item bottom" data-go="66">${ico('settings')}Settings</div></aside><main class="workspace"><header class="top compact-header ${posBrowse?'is-pos-header':''}"><div class="header-start"><h1>${esc(title)}</h1>${posBrowse?`<nav class="pos-mode" aria-label="POS view"><button data-go="10" class="${s.id!==119?'selected':''}">Groups</button><button data-go="119" class="${s.id===119?'selected':''}">Quick list</button></nav>`:''}</div><div class="top-right">${s.area==='pos'?headerIcon('search','Search menu','data-pos-search-open'):''}${isOrders?`<button class="header-icon ${orderFilterIsOpen(s)?'selected':''}" data-order-filters aria-label="Order filters${window.ORDER_FILTER_VALUE!=='All orders'?', 1 active':''}" title="Show or hide filters" aria-expanded="${orderFilterIsOpen(s)}" aria-controls="order-filter-panel">${ico('filter')}${window.ORDER_FILTER_VALUE!=='All orders'?'<span class="filter-count">1</span>':''}</button>${headerIcon('refresh','Refresh orders','data-action="demo"')}<button class="header-new-order primary" data-go="10">${ico('plus')}<span>New order</span></button>`:''}${headerIcon('user','Register and profile','data-go="96"')}</div></header>${orderTabs(s)}${orderFilterPanel(s)}<div class="content ${['pos','customise'].includes(s.kind)?'pos-content':''}">${body}</div></main><nav class="mobile-nav">${nav.map(([i,t,n])=>`<div class="nav-item ${i===active?'active':''}" data-go="${n}">${ico(i)}${t}</div>`).join('')}</nav></div>`;}
function handleUIMessage(data){if(data.ui==='order-filters'){window.ORDER_FILTER_OPEN=!(window.ORDER_FILTER_OPEN??current===2);render();return true;}if(data.ui==='order-filter'){window.ORDER_FILTER_VALUE=data.value;window.ORDER_FILTER_OPEN=true;render();return true;}return false;}
window.makeScreen=function(s){let overlay=['overlay','date','confirm','cash','keypad','product','receipt','tvpreview','system'].includes(s.kind)||s.id===81;let page;if(s.kind==='detail')page=orderDetailModal(s);else if([4,62,63].includes(s.id))page=printModal(s);else if(s.kind==='login')page=login(s);else if(overlay){let base={...s,title:s.area==='pos'?'Take an order':s.area==='catalogue'?'Menu management':s.area==='orders'?'Live orders':s.title};let bg=s.area==='pos'?pos({id:118}):s.area==='catalogue'?catalogue({id:77,primary:'Add product'}):s.area==='orders'?orders({id:1}):s.area==='marketing'?marketing({id:40,primary:'Review campaign'}):s.area==='coupons'?coupons({id:43}):s.area==='tv-menu'?tv({id:93}):settings();page=shell(base,bg).replace('<div class="app">','<div class="app" inert>')+`<div class="overlay"><section class="dialog ${['product','tvpreview'].includes(s.kind)?'wide':''} ${s.kind==='confirm'?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(s.title)}"><header class="dialog-head"><div><h2>${esc(s.title)}</h2></div><button class="close" data-close aria-label="Close">×</button></header><div class="dialog-body">${overlayBody(s)}</div><footer class="dialog-foot">${btn(['system','receipt','tvpreview'].includes(s.kind)?'Close':'Cancel','','close')}${btn(s.primary,s.kind==='confirm'?'danger':'primary',s.id===120?'go121':'demo')}</footer></section></div>`;}else if(s.kind==='customise')page=shell(s,customise(s));else if(s.kind==='cart-review')page=shell(s,cartReview());else page=shell(s,bodyFor(s));if(s.area==='pos'&&['pos','customise','cart-review'].includes(s.kind)){const overlay=posSearch(s);if(overlay)page=page.replace('<div class="app">','<div class="app" inert>')+overlay;}return page;};
window.bindScreen=function(){document.addEventListener('click',e=>{const scroll={content:document.querySelector('.content')?.scrollTop||0,menu:document.querySelector('.menu-pane')?.scrollTop||0,cart:document.querySelector('.cart-body')?.scrollTop||0};if(e.target.closest('[data-detail-close]')){parent.postMessage({detailClose:true},'*');return;}if(e.target.closest('[data-print-close]')){parent.postMessage({printClose:true},'*');return;}const printer=e.target.closest('[data-print-printer]');if(printer){if(printer.disabled)return;document.querySelectorAll('[data-print-printer]').forEach(b=>b.disabled=true);parent.postMessage({printer:printer.dataset.printPrinter},'*');return;}const copy=e.target.closest('[data-print-copy]');if(copy){parent.postMessage({printCopy:copy.dataset.printCopy},'*');return;}if(e.target.closest('[data-pos-back]')){parent.postMessage({pos:'back',scroll},'*');return;}const selectLayout=e.target.closest('[data-layout-select]');if(selectLayout){parent.postMessage({layout:'select',type:selectLayout.dataset.layoutSelect,key:selectLayout.dataset.layoutKey},'*');return;}const level=e.target.closest('[data-layout-level]');if(level){parent.postMessage({layout:'level',value:level.dataset.layoutLevel},'*');return;}const move=e.target.closest('[data-layout-move]');if(move){parent.postMessage({layout:'move',value:move.dataset.layoutMove},'*');return;}if(e.target.closest('[data-layout-hidden-toggle]')){parent.postMessage({layout:'show-hidden'},'*');return;}if(e.target.closest('[data-layout-save]')){parent.postMessage({layout:'save'},'*');return;}if(e.target.closest('[data-layout-apply]')){parent.postMessage({layout:'apply'},'*');return;}if(e.target.closest('[data-order-filters]')){parent.postMessage({ui:'order-filters'},'*');return;}const orderFilter=e.target.closest('[data-order-filter]');if(orderFilter){parent.postMessage({ui:'order-filter',value:orderFilter.dataset.orderFilter},'*');return;}const product=e.target.closest('[data-pos-product]');if(product){parent.postMessage({pos:'product',name:product.dataset.product,group:product.dataset.productGroup,price:product.dataset.price,hasAddons:product.dataset.hasAddons==='true',scroll},'*');return;}if(e.target.closest('[data-pos-search-clear]')){const input=document.querySelector('[data-pos-search-input]');input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();return;}if(e.target.closest('[data-pos-done]')){parent.postMessage({pos:'done'},'*');return;}if(e.target.closest('[data-pos-search-open]')){parent.postMessage({pos:'search',scroll},'*');return;}if(e.target.closest('[data-pos-search-close]')){parent.postMessage({pos:'close-search'},'*');return;}const edit=e.target.closest('[data-pos-edit]');if(edit){parent.postMessage({pos:'edit',line:edit.dataset.posEdit},'*');return;}const qtyAction=e.target.closest('[data-pos-qty]');if(qtyAction){parent.postMessage({pos:'qty',line:qtyAction.dataset.line,direction:qtyAction.dataset.posQty,scroll},'*');return;}const remove=e.target.closest('[data-pos-remove]');if(remove){parent.postMessage({pos:'remove',line:remove.dataset.posRemove,scroll},'*');return;}let go=e.target.closest('[data-go]');let act=e.target.closest('[data-action]');if(go){parent.postMessage({go:+go.dataset.go,group:go.dataset.group,product:go.dataset.product,productGroup:go.dataset.productGroup,price:go.dataset.price,editing:go.dataset.cartEdit==='true',quantity:go.dataset.quantity,salt:go.dataset.salt,vinegar:go.dataset.vinegar,scroll},'*');return;}if(e.target.closest('[data-close]')||act?.dataset.action==='close'){parent.postMessage({close:true},'*');return;}let toggle=e.target.closest('[data-toggle]');if(toggle){let on=toggle.getAttribute('aria-checked')!=='true';toggle.setAttribute('aria-checked',String(on));toggle.querySelector('.toggle')?.classList.toggle('off',!on);return;}let addon=e.target.closest('[data-addon-choice]');if(addon){parent.postMessage({pos:'modifier',group:addon.closest('[data-addon-group]').dataset.addonGroup,value:addon.querySelector('span').textContent,scroll},'*');return;}let chip=e.target.closest('[data-choice]');if(chip){chip.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.remove('selected'));chip.classList.add('selected');return;}if(act?.dataset.action.startsWith('go')){parent.postMessage({go:+act.dataset.action.slice(2),scroll},'*');return;}if(act||e.target.closest('[data-add]')){let t=document.createElement('div');t.className='toast';t.textContent='Design preview only · No business data changed';document.body.append(t);setTimeout(()=>t.remove(),2200);}});document.addEventListener('change',e=>{if(e.target.matches('[data-layout-setting]'))parent.postMessage({layout:'setting',key:e.target.dataset.layoutSetting,value:e.target.value},'*');if(e.target.matches('[data-layout-preview-group]'))parent.postMessage({layout:'preview-group',value:e.target.value},'*');if(e.target.matches('[data-layout-load]'))parent.postMessage({layout:'load',value:e.target.value},'*');if(e.target.matches('[data-layout-device]'))parent.postMessage({layout:'device',value:e.target.value},'*')});document.addEventListener('input',e=>{if(e.target.matches('.search input')){const q=e.target.value.toLowerCase();document.querySelectorAll('.group-grid .group-card,.menu-pane .products .product-tile,.pos-search .product-tile,.pos-search .group-card').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q));const noResults=document.querySelector('.search-no-results');if(noResults)noResults.hidden=!!document.querySelector('.pos-search .product-tile:not([hidden]),.pos-search .group-card:not([hidden])')}});document.addEventListener('keydown',e=>{if(e.key==='Tab'){const dialogs=[...document.querySelectorAll('[role=dialog]')].filter(x=>!x.closest('[inert]'));const dialog=dialogs.at(-1);if(dialog){const nodes=[...dialog.querySelectorAll('button:not([disabled]),input,select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first?.focus();}}}if(e.key==='Escape'&&document.querySelector('[data-print-close]')){e.preventDefault();parent.postMessage({printClose:true},'*');return;}if(e.key==='Escape'&&document.querySelector('[data-detail-close]')){e.preventDefault();parent.postMessage({detailClose:true},'*');return;}if(e.key==='Escape'&&document.querySelector('.pos-search')){e.preventDefault();parent.postMessage({pos:'close-search'},'*')}});document.addEventListener('submit',e=>e.preventDefault());};

// Overlay context is owned by the caller, independent from the order's status.
window.ORDER_DETAIL_ORIGIN=null;window.PRINT_ORIGIN=null;window.PRINT_JOBS=[];window.PRINT_COPY='Customer copy';
function screenById(id){return SCREENS.find(x=>x.id===id)||SCREENS.find(x=>x.id===1);}
function callerBackdrop(id){const origin=screenById(id);return shell(origin,bodyFor(origin)).replace('<div class="app">','<div class="app" inert aria-hidden="true">');}
function orderDetailModal(s){const origin=window.ORDER_DETAIL_ORIGIN?.id||(s.id===115?6:1);return callerBackdrop(origin)+`<div class="overlay order-detail-overlay"><section class="dialog order-detail-dialog" role="dialog" aria-modal="true" aria-labelledby="order-detail-title"><header class="dialog-head"><div><h2 id="order-detail-title">Order #${s.id===115?'P058':'P019'}</h2><span class="hint">Alex Taylor · ${s.id===115?'Completed':'Pickup at 6:45 pm'}</span></div><button class="close" data-detail-close aria-label="Close order details">×</button></header><div class="dialog-body">${detail(s).replace(/<div class="page-actions">[\s\S]*$/, '')}</div><footer class="dialog-foot">${btn('Print order','','go4')}<span class="spacer"></span>${s.id===115?badge('Paid · Completed','green'):btn('Cancel order','danger','demo')+btn('Mark ready','primary','demo')}</footer></section></div>`;}
function printModal(s){let caller=window.PRINT_ORIGIN?.id||(s.id===4?3:57);let bg=[3,115].includes(caller)?orderDetailModal(screenById(caller)):callerBackdrop(caller);bg=bg.replace('<section class="dialog order-detail-dialog"','<section inert aria-hidden="true" class="dialog order-detail-dialog"');return bg+`<div class="overlay print-overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(s.id===62?'Choose printer':s.title)}"><header class="dialog-head"><h2>${esc(s.id===62?'Choose printer':s.title)}</h2><button class="close" data-print-close aria-label="Close print dialog">×</button></header><div class="dialog-body">${s.id===63&&[3,115].includes(caller)?`<div class="receipt"><h3>PAPPA’S OCEAN CATCH</h3><p>ORDER #${caller===115?'P058':'P019'} · ${esc(window.PRINT_COPY)}</p>${line('3 × Potato cake','$6.00','Chicken salt')}${line('1 × Dim sim · fried','$1.80')}${line('1 × Chips','$6.00','Chicken salt · Pack separately')}${line('Total','$13.80')}<p>SIMULATOR PREVIEW · No physical print requested</p></div>`:overlayBody(s)}</div>${s.id===63?'<footer class="dialog-foot"><button data-print-close>Close preview</button></footer>':''}</section></div>`;}
function handleOverlayMessage(data){
if(data.go&&[3,115].includes(data.go)){if(![3,115,4,62,63].includes(current))window.ORDER_DETAIL_ORIGIN={id:current,scroll:data.scroll};current=data.go;render();return true;}
if(data.detailClose){const origin=window.ORDER_DETAIL_ORIGIN||{id:current===115?6:1};current=origin.id;window.POS_RETURN_SCROLL=origin.scroll;window.ORDER_DETAIL_ORIGIN=null;render();return true;}
if(data.go&&[4,62,63].includes(data.go)){if(![4,62,63].includes(current))window.PRINT_ORIGIN={id:current,scroll:data.scroll};current=data.go;render();return true;}
if(data.printCopy){window.PRINT_COPY=data.printCopy;current=62;render();return true;}
if(data.printer){if(current!==62)return true;if(/simulator/i.test(data.printer)){current=63;render();return true;}window.PRINT_JOBS.push({printer:data.printer,copy:window.PRINT_COPY,caller:window.PRINT_ORIGIN?.id||57});const origin=window.PRINT_ORIGIN||{id:57};current=origin.id;window.POS_RETURN_SCROLL=origin.scroll;window.PRINT_ORIGIN=null;render();const frame=document.getElementById('preview');frame.addEventListener('load',()=>{const t=frame.contentDocument.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent='Print simulated · '+data.printer;frame.contentDocument.body.append(t);setTimeout(()=>t.remove(),2400)},{once:true});return true;}
if(data.printClose){const origin=window.PRINT_ORIGIN||{id:current===4?3:57};current=origin.id;window.POS_RETURN_SCROLL=origin.scroll;window.PRINT_ORIGIN=null;render();return true;}return false;}
